using namespace std;

int n, s;
int memo[1024][1000];

int search(int stat, int sum, int dep) {
    if (dep == n) return (s == sum);
    if (sum >= 1000) return 0; // Early exit if sum exceeds limit
    if (~memo[stat][sum]) return memo[stat][sum];

    int cnt = 0;
    for (int i = 0; i < 10; i++) {
        if ((stat & (1 << i)) == 0) {
            cnt += search(stat | (1 << i), sum + i * (n - dep), dep + 1);
        }
    }
    return memo[stat][sum] = cnt;
}

int main() {
    while (~scanf("%d%d", &n, &s)) {
        if (n > 10 || s >= 1000) {
            puts("0");
            continue;
        }
        for (int i = 0; i < 1024; i++) 
            for (int j = 0; j < 1000; j++) 
                memo[i][j] = -1;

        int result = search(0, 0, 0);
        printf("%d\n", result);
    }
    return 0;
}

